import{_ as o,o as e,c as a,ag as p}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第78章 生日","description":"","frontmatter":{},"headers":[],"relativePath":"第78章_生日.md","filePath":"第78章_生日.md"}'),_={name:"第78章_生日.md"};function u(r,t,q,n,s,c){return e(),a("div",null,[...t[0]||(t[0]=[p('<h1 id="第78章-生日" tabindex="-1">第78章 生日 <a class="header-anchor" href="#第78章-生日" aria-label="Permalink to &quot;第78章 生日&quot;">​</a></h1><p>她生日那天，我送了她一样她从来没说要的东西。一块垫子。事情是从三月开始的。她给我拍过她的床。床垫中间凹了一块，她在那块凹下面垫了两本杂志，说&quot;现在还行&quot;。我记住了&quot;现在还行&quot;这四个字。她这个人讲什么东西，讲到&quot;还行&quot;，就是不行。她讲饭&quot;还行&quot;，她就没吃；她讲睡&quot;还行&quot;，她前一天是三点睡的；她讲心情&quot;还行&quot;，那天她一定没去上课。</p><p>所以四月中我开始看那个垫子。我们这边的记忆棉枕，一块薄垫，一米九乘九十，价格从一百八到六百多。我那时候手上有四百二十。这四百二十是那一年我从仓库那笔活里剩下的，加上我四月那份寄东西的抽成。我买了一块三百八的。剩下四十我买了箱子和一包干燥剂。我寄出去以前做了一件事。我拿尺子量了那个箱子的尺寸，我算了一下她那个床。她跟我讲过她那个床：床框是铁的，里面能塞东西的空间，深度大约十厘米。我把垫子厚度算进去了，十四厘米。我那时候想到的是：她可以裁。我没想到她能怎么裁。</p><p>她收到那天是四月二十七号。她那边的下午四点，我这边夜里十一点。她说，今天有人给我发了生日祝福。我说，谁。她说，系统。一个软件给我弹了一个横幅，说今天我生日。我妈给我打电话了，她打电话是因为她要问我那笔钱。我妹给我画了一张东西，画得很难看，画了一个很长的人，她说那是你。我这辈子第一次知道，一个软件比我妈准时。我说，那个垫子你收到了吗。她说，收到了。我今天拆了。我说，怎么样。她没回。过了大概七分钟，她发了一张图。那张图是她那张床。垫子铺在上面，两边翘起来，像一件不合身的外套。她说，进不去。我说，什么叫进不去。她说，你们的床垫是厚的，我这里这个床是个铁框。我把这个垫子塞进去，它顶出来了，顶出来以后我那个床单铺不平。我现在睡在上面，我半夜会滚到那个边上。我说，你裁一下。她说，我裁不了。你寄过来的时候那个包装我没敢拆坏，我拿剪刀试了一下，里面不是棉，是一整块东西。裁开它会更厚。</p><p>我看着那张图，坐在椅子上。我那时候心里非常清楚我做了一件什么事。我算了一整个月。我算她的床有多长，我算她那个房东会不会换床垫，我算我出不出得起。我什么都算了。我漏掉的那一样，是我从来没有摸过她那张床。我不知道铁的会响。我不知道她那个床框是焊死的，边上有一圈凸出来的边。我不知道这些，是因为我一次也没在那张床上躺过。我送了她一块十四厘米的、我这辈子睡都没睡过的东西。</p><p>我给她打了一段话。我打的是：对不起，我没想到你那个床有边。打完我看着这句。我把它删了。我删的原因是：她生日。一个人在她生日这一天，被人提醒&quot;我为你花了一个月，结果我用不上&quot;。我把这句删了。我发的是：那你铺在上面睡，别塞。她说：我试了，滑。我说：那你明天再说，今天你生日。她说：我今天不是生日。我今天是我二十八号。我们这边今天有课，我八点的课，我六点起的，我把那个垫子从床上推下去推了三回。</p><p>我说：你现在在哪儿。她说：我在图书馆。我跟你说这个不是怪你。我就是想让你知道，你今天送了我一个东西，我把它推下去了三次。我以前收到这种东西，我都是扔了的。我今天没有扔。我今天把它塞在我柜子最里面，我拿衣服盖住了。我这样是好事还是坏事，我不知道。</p><p>那天夜里她说了一句别的。她说，你知道吗，我今天第一次发现我们家那个日历有问题。我说，什么日历。她说，我妈每年在她那个小日历上给我妹的生日画一个圈。画了很多年。我今天回去翻我们家那个旧挂历，我从头翻到尾。我生日那天是空的。我不怪她。因为她不记得我生日那天，她记得的是我妹考试那天。我说，那你现在干嘛。她说，我在吃一份鸡肉。我今天过生日，我买了一份大份的。十二块。我说，好吃吗。她说，不好吃，太咸。但是我吃完了。我说，那挺好。她说，你别&quot;那挺好&quot;，你这个&quot;那挺好&quot;是在忍。我说，我没忍。你在忍你不用说对不起。</p><p>我坐在那儿。我说，对不起，我没想到你那个床有边。我最后还是发了。她隔了很久。然后她说了一句我记到现在的话。她说，我知道。你没想到这件事，就是你送我这个东西里面最真的那部分。你要是想到了，你就不会买这么厚。你买这么厚，说明你以为你在跟一个有床的人说话。我这边这些人，他们给我买东西的时候，都以为我有一个正常的床。只有你算错了，因为你是真的在替我算。</p><p>我说，那你今晚把它拿出来。她说，干嘛。我说，铺在上面，你在上面睡一次。她说，滑。我把头那边压在你的旧杂志底下。她没回。下午三点四十，她那边是早上八点四十，她去上课了。第二天她上线，第一句：我那天晚上睡在那上面了。滚下来两次。但是那一晚我没有腰疼。你的那个垫子，是有用的。只是没用在它该用的地方。</p><p>那天下午我拿本子记下了这一件事。我写：她生日，我送错了一样东西。我写：她没哭。她把那个东西塞在柜子最里面，用衣服盖住。我写：盖住，就是她还留着。后来每回想到她生日，我先在脑子里看见那张两边翘起来的垫子，和她把它从床上推下去的三回。她没说扔，也没说留，只是拿衣服盖上了——那是我认识她以来，最接近&quot;收下&quot;的一次。</p>',11)])])}const l=o(_,[["render",u]]);export{d as __pageData,l as default};
